  80:     public void disconnectHfpDevice(String id) {
  81:         SimulatedBluetoothDevice simulatedBluetoothDevice = mDeviceMap.remove(id);
  82:         if (simulatedBluetoothDevice == null) {
  83:             return;
  84:         }
  85:         mDeviceList.remove(simulatedBluetoothDevice.getBluetoothDevice());
  86:         simulatedBluetoothDevice.disconnect();
  87:         mHfpDeviceListLiveData.postValue(mDeviceList);
  88:     }
  89: 
  90:     private SimulatedBluetoothDevice prepareNewDevice(int id) {
  91:         String contactDataFile = TestData.getContactDataFile(id);
  92:         String callLogDataFile = TestData.getCallLogDataFile(id);
  93:         SimulatedBluetoothDevice simulatedBluetoothDevice = new SimulatedBluetoothDevice(
  94:                 id, mContactDataHandler, mCallLogDataHandler, contactDataFile, callLogDataFile);
  95: 
  96:         return simulatedBluetoothDevice;
  97:     }
  98: 
  99:     public MutableLiveData<Integer> getBluetoothStateLiveData() {
 100:         return mBluetoothStateLiveData;
 101:     }
 102: 
 103:     public MutableLiveData<Set<BluetoothDevice>> getBluetoothPairListLiveData() {
 104:         return mBluetoothPairListLiveData;
 105:     }
 106: 
 107:     public MutableLiveData<List<BluetoothDevice>> getHfpDeviceListLiveData() {
 108:         return mHfpDeviceListLiveData;
 109:     }
 110: }

