  61: /**
  62:  * The entry point for all interactions between UI and telecom.
  63:  */
  64: @Singleton
  65: public final class UiCallManager {
  66:     private static String TAG = "CD.TelecomMgr";
  67: 
  68:     private static final String EVENT_SCO_CONNECT = "com.android.bluetooth.hfpclient.SCO_CONNECT";
  69:     private static final String EVENT_SCO_DISCONNECT =
  70:             "com.android.bluetooth.hfpclient.SCO_DISCONNECT";
  71:     private static final String ACTION_DIRECT_SEND = "ACTION_DIRECT_SEND";
  72: 
  73:     private Context mContext;
  74:     private final TelecomManager mTelecomManager;
  75:     private final PhoneAccountManager mPhoneAccountManager;
  76:     private InCallServiceImpl mInCallService;
  77:     private LiveData<BluetoothDevice> mCurrentHfpDeviceLiveData;
  78:     private final CallLifecycleCoordinator mLifecycle = new CallLifecycleCoordinator();
  79: 
  80:     @Inject
  81:     UiCallManager(
  82:             @ApplicationContext Context context,
  83:             TelecomManager telecomManager,
  84:             PhoneAccountManager phoneAccountManager,
  85:             @Named("Hfp") LiveData<BluetoothDevice> currentHfpDeviceLiveData) {
  86:         L.d(TAG, "SetUp");
  87:         mContext = context;
  88:         mTelecomManager = telecomManager;
  89:         mPhoneAccountManager = phoneAccountManager;
  90:         mCurrentHfpDeviceLiveData = currentHfpDeviceLiveData;
  91: 
  92:         Intent intent = new Intent(context, InCallServiceImpl.class);
  93:         intent.setAction(InCallServiceImpl.ACTION_LOCAL_BIND);
  94:         context.bindService(intent, mInCallServiceConnection, Context.BIND_AUTO_CREATE);
  95:     }
  96: 
  97:     private final ServiceConnection mInCallServiceConnection = new ServiceConnection() {
  98: 
  99:         @Override
 100:         public void onServiceConnected(ComponentName name, IBinder binder) {
 101:             L.d(TAG, "onServiceConnected: %s, service: %s", name, binder);
 102:             mInCallService = ((InCallServiceImpl.LocalBinder) binder).getService();
 103:             mLifecycle.onServiceConnected();
 104:         }
 105: 
 106:         @Override
 107:         public void onServiceDisconnected(ComponentName name) {
 108:             L.d(TAG, "onServiceDisconnected: %s", name);
 109:             mInCallService = null;
 110:             mLifecycle.onServiceDisconnected();
 111:         }
 112:     };
 113: 
 114:     /**
 115:      * Tears down the {@link UiCallManager}. Calling this function will null out the global
 116:      * accessible {@link UiCallManager} instance. Remember to re-initialize the
 117:      * {@link UiCallManager}.
 118:      */
 119:     public void tearDown() {
 120:         if (mInCallService != null) {
 121:             mContext.unbindService(mInCallServiceConnection);
 122:             mInCallService = null;
 123:         }
 124:         // Clear out the mContext reference to avoid memory leak.
 125:         mLifecycle.close();
 126:         mContext = null;
 127:     }
 128: 
 129:     public boolean getMuted() {
 130:         L.d(TAG, "getMuted");
 131:         if (mInCallService == null) {
 132:             return false;
 133:         }
 134:         CallAudioState audioState = mInCallService.getCallAudioState();
 135:         return audioState != null && audioState.isMuted();
 136:     }
 137: 
 138:     public void setMuted(boolean muted) {
 139:         L.d(TAG, "setMuted: " + muted);
 140:         if (mInCallService == null) {
 141:             return;
 142:         }
 143:         mInCallService.setMuted(muted);
 144:     }
 145: 
 146:     public int getSupportedAudioRouteMask() {
 147:         L.d(TAG, "getSupportedAudioRouteMask");
 148: 
 149:         CallAudioState audioState = getCallAudioStateOrNull();
 150:         return audioState != null ? audioState.getSupportedRouteMask() : 0;
 151:     }
 152: 
 153:     /** Returns a list of supported CallAudioRoute for the given {@link PhoneAccountHandle}. */
 154:     public List<Integer> getSupportedAudioRoute(@Nullable PhoneAccountHandle phoneAccountHandle) {
 155:         List<Integer> audioRouteList = new ArrayList<>();
 156: 
 157:         BluetoothDevice device = mPhoneAccountManager.getMatchingDevice(phoneAccountHandle);
 158:         if (device != null) {
 159:             // if this is bluetooth phone call, we can only select audio route between vehicle
 160:             // and phone.
 161:             // Vehicle speaker route.
 162:             audioRouteList.add(CallAudioState.ROUTE_BLUETOOTH);
 163:             // Headset route.
 164:             audioRouteList.add(CallAudioState.ROUTE_EARPIECE);
 165:         } else {
 166:             // Most likely we are making phone call with on board SIM card.
 167:             int supportedAudioRouteMask = getSupportedAudioRouteMask();
 168: 
 169:             if ((supportedAudioRouteMask & CallAudioState.ROUTE_EARPIECE) != 0) {
 170:                 audioRouteList.add(CallAudioState.ROUTE_EARPIECE);
 171:             } else if ((supportedAudioRouteMask & CallAudioState.ROUTE_WIRED_HEADSET) != 0) {
 172:                 audioRouteList.add(CallAudioState.ROUTE_WIRED_HEADSET);
 173:             }
 174:             if ((supportedAudioRouteMask & CallAudioState.ROUTE_BLUETOOTH) != 0) {
 175:                 audioRouteList.add(CallAudioState.ROUTE_BLUETOOTH);
 176:             }
 177:             if ((supportedAudioRouteMask & CallAudioState.ROUTE_SPEAKER) != 0) {
 178:                 audioRouteList.add(CallAudioState.ROUTE_SPEAKER);
 179:             }
 180:         }
 181: 
 182:         return audioRouteList;
 183:     }
 184: 
 185:     /**
 186:      * Returns the current audio route given the SCO state. See {@link CallDetail#getScoState()}.
 187:      * The available routes are defined in {@link CallAudioState}.
 188:      */
 189:     public int getAudioRoute(int scoState) {
 190:         if (scoState != CallDetail.STATE_AUDIO_ERROR) {
 191:             if (scoState == CallDetail.STATE_AUDIO_CONNECTED) {
 192:                 return CallAudioState.ROUTE_BLUETOOTH;
 193:             } else {
 194:                 return CallAudioState.ROUTE_EARPIECE;
 195:             }
 196:         } else {
 197:             CallAudioState audioState = getCallAudioStateOrNull();
 198:             int audioRoute = audioState != null ? audioState.getRoute() : 0;
 199:             L.d(TAG, "getAudioRoute " + audioRoute);
 200:             return audioRoute;
 201:         }
 202:     }
 203: 
 204:     /**
 205:      * Re-route the audio out phone of the ongoing phone call.
 206:      */
 207:     public void setAudioRoute(int audioRoute, Call primaryCall) {
 208:         if (primaryCall == null) {
 209:             return;
 210:         }
 211: 
 212:         boolean isConference = !primaryCall.getChildren().isEmpty()
 213:                 && primaryCall.getDetails().hasProperty(Call.Details.PROPERTY_CONFERENCE);
 214:         Call call = isConference ? primaryCall.getChildren().get(0) : primaryCall;
 215: 
 216:         if (audioRoute == CallAudioState.ROUTE_BLUETOOTH) {
 217:             call.sendCallEvent(EVENT_SCO_CONNECT, null);
 218:             setMuted(false);
 219:         } else if ((audioRoute & CallAudioState.ROUTE_WIRED_OR_EARPIECE) != 0) {
 220:             call.sendCallEvent(EVENT_SCO_DISCONNECT, null);
 221:         }
 222:         // TODO: Implement routing audio if current call is not a bluetooth call.
 223:     }
 224: 
 225:     private CallAudioState getCallAudioStateOrNull() {
 226:         return mInCallService != null ? mInCallService.getCallAudioState() : null;
 227:     }
 228: 
 229:     /**
 230:      * Places call through TelecomManager
 231:      *
 232:      * @return {@code true} if a call is successfully placed, false if number is invalid.
 233:      */
 234:     public boolean placeCall(String number) {
 235:         if (isValidNumber(number)) {
 236:             Uri uri = Uri.fromParts("tel", number, null);
 237:             L.d(TAG, "android.telecom.TelecomManager#placeCall: %s", number);
 238: 
 239:             try {
 240:                 mTelecomManager.placeCall(uri, null);
 241:                 return true;
 242:             } catch (IllegalStateException e) {
 243:                 Toast.makeText(mContext, R.string.error_telephony_not_available,
 244:                         Toast.LENGTH_SHORT).show();
 245:                 L.w(TAG, e.toString());
 246:                 return false;
 247:             }
 248:         } else {
 249:             L.d(TAG, "invalid number dialed", number);
 250:             Toast.makeText(mContext, R.string.error_invalid_phone_number,
 251:                     Toast.LENGTH_SHORT).show();
 252:             return false;
 253:         }
 254:     }
 255: 
 256:     /**
 257:      * Places a SMS with assisant
 258:      */
 259:     public boolean placeSms(Activity activity, String number, String name, String uid) {
 260:         BluetoothDevice device = mCurrentHfpDeviceLiveData.getValue();
 261: 
 262:         Bundle bundle = new Bundle();
 263:         bundle.putString(CarVoiceInteractionSession.KEY_ACTION, VOICE_ACTION_SEND_SMS);
 264:         bundle.putString(CarVoiceInteractionSession.KEY_PHONE_NUMBER, number);
 265:         bundle.putString(CarVoiceInteractionSession.KEY_RECIPIENT_NAME, name);
 266:         bundle.putString(CarVoiceInteractionSession.KEY_RECIPIENT_UID, uid);
 267:         bundle.putString(CarVoiceInteractionSession.KEY_DEVICE_ADDRESS, device.getAddress());
 268:         bundle.putString(CarVoiceInteractionSession.KEY_DEVICE_NAME, device.getName());
 269: 
 270:         Context context = activity.getApplicationContext();
 271:         Intent intent = new Intent(context, MessagingService.class)
 272:                 .setAction(ACTION_DIRECT_SEND)
 273:                 .addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP | Intent.FLAG_ACTIVITY_SINGLE_TOP)
 274:                 .setClass(context, MessagingService.class);
 275: 
 276:         int requestCode = ACTION_DIRECT_SEND.hashCode();
 277:         PendingIntent pendingIntent = PendingIntent.getForegroundService(
 278:                 context, requestCode, intent,
 279:                 PendingIntent.FLAG_ONE_SHOT | PendingIntent.FLAG_IMMUTABLE);
 280: 
 281:         bundle.putParcelable(KEY_SEND_PENDING_INTENT, pendingIntent);
 282:         activity.showAssist(bundle);
 283: 
 284:         return true;
 285:     }
 286: 
 287:     /**
 288:      * Runs basic validation check of a phone number, to verify it is not empty.
 289:      */
 290:     private boolean isValidNumber(String number) {
 291:         if (TextUtils.isEmpty(number)) {
 292:             return false;
 293:         }
 294:         return true;
 295:     }
 296: 
 297:     public void callVoicemail() {
 298:         L.d(TAG, "callVoicemail");
 299: 
 300:         String voicemailNumber = TelecomUtils.getVoicemailNumber(mContext);
 301:         if (TextUtils.isEmpty(voicemailNumber)) {
 302:             L.w(TAG, "Unable to get voicemail number.");
 303:             return;
 304:         }
 305:         placeCall(voicemailNumber);
 306:     }
 307: 
 308:     /** Check if emergency call is supported by any phone account. */
 309:     public boolean isEmergencyCallSupported() {
 310:         List<PhoneAccountHandle> phoneAccountHandleList =
 311:                 mTelecomManager.getCallCapablePhoneAccounts();
 312:         for (PhoneAccountHandle phoneAccountHandle : phoneAccountHandleList) {
 313:             PhoneAccount phoneAccount = mTelecomManager.getPhoneAccount(phoneAccountHandle);
 314:             L.d(TAG, "phoneAccount: %s", phoneAccount);
 315:             if (phoneAccount != null && phoneAccount.hasCapabilities(
 316:                     PhoneAccount.CAPABILITY_PLACE_EMERGENCY_CALLS)) {
 317:                 return true;
 318:             }
 319:         }
 320:         return false;
 321:     }
 322: 
 323:     /** Return the current active call list from delegated {@link InCallServiceImpl} */
 324:     public List<Call> getCallList() {
 325:         return mInCallService == null ? Collections.emptyList() : mInCallService.getCallList();
 326:     }
 327: }
