  64:                 @Override
  65:                 public boolean onTelecomCallAdded(Call telecomCall) {
  66:                     notifyCallAdded(telecomCall);
  67:                     notifyCallListChanged();
  68:                     return false;
  69:                 }
  70: 
  71:                 @Override
  72:                 public boolean onTelecomCallRemoved(Call telecomCall) {
