  46: /**
  47:  * Voice interaction entry point. This service is kept running for as long as this application
  48:  * is set as the default voice interaction service.
  49:  */
  50: public class InteractionService extends VoiceInteractionService {
  51:     private static final String TAG = "Mica.InteractionService";
  52:     private static final String CHANNEL_ID = "Mica";
  53:     private static final int NOTIFICATION_ID = 1;
  54:     private NotificationManager mNotificationManager;
  55:     public static final String LOCAL_SERVICE_ACTION = "com.android.car.voicecontrol.local";
  56:     public static final String LOCAL_SERVICE_CMD_SETUP_CHANGED = "setup-changed";
  57:     private static final List<String> SUPPORTED_VOICE_ACTIONS = Arrays.asList(
  58:             CarVoiceInteractionSession.VOICE_ACTION_READ_NOTIFICATION,
  59:             CarVoiceInteractionSession.VOICE_ACTION_REPLY_NOTIFICATION,
  60:             CarVoiceInteractionSession.VOICE_ACTION_HANDLE_EXCEPTION,
  61:             CarVoiceInteractionSession.VOICE_ACTION_SEND_SMS
  62:     );
  63:     public static final List<String> REQUIRED_PERMISSIONS = Arrays.asList(
  64:             Manifest.permission.RECORD_AUDIO,
  65:             Car.PERMISSION_SPEED,
  66:             Manifest.permission.CALL_PHONE,
  67:             Manifest.permission.READ_PHONE_STATE,
  68:             Manifest.permission.SEND_SMS,
  69:             Manifest.permission.READ_CONTACTS
  70:     );
  71:     private ContactsProvider mContactsProvider;
  72: 
  73:     private final ILocalService.Stub mBinder = new ILocalService.Stub() {
  74:         @Override
  75:         public boolean isSetupComplete() {
  76:             return InteractionService.this.isSetupComplete();
  77:         }
  78: 
  79:         @Override
  80:         public void registerListener(ILocalServiceListener listener) {
  81:             mListeners.register(listener);
  82:         }
  83: 
  84:         @Override
  85:         public void unregisterListener(ILocalServiceListener listener) {
  86:             mListeners.unregister(listener);
  87:         }
  88: 
  89:         @Override
  90:         public String getVoice() {
  91:             return PreferencesController.getInstance(InteractionService.this).getVoice();
  92:         }
  93: 
  94:         @Override
  95:         public void setVoice(String name) {
  96:             PreferencesController.getInstance(InteractionService.this).setVoice(name);
  97:         }
  98: 
  99:         @Override
 100:         public String getUsername() {
 101:             String value = PreferencesController.getInstance(InteractionService.this).getUsername();
 102:             Log.d(TAG, "getUsername(): " + value);
 103:             return value;
 104:         }
 105: 
 106:         @Override
 107:         public void setUsername(String value) {
 108:             Log.d(TAG, "setUsername: " + value);
 109:             PreferencesController.getInstance(InteractionService.this).setUsername(value);
 110:             onSetupChanged();
 111:         }
 112: 
 113:         @Override
 114:         public boolean hasAllPermissions() {
 115:             return InteractionService.hasAllPermissions(InteractionService.this);
 116:         }
 117: 
 118:         @Override
 119:         public boolean isNotificationListener() {
 120:             return InteractionService.this.isNotificationListener();
 121:         }
