 128:     private final RemoteCallbackList<ILocalServiceListener> mListeners = new RemoteCallbackList<>();
 129: 
 130:     @Override
 131:     public IBinder onBind(Intent intent) {
 132:         Log.d(TAG, "onBind: " + intent);
 133:         if (LOCAL_SERVICE_ACTION.equals(intent.getAction())) {
 134:             return mBinder;
 135:         }
 136:         return super.onBind(intent);
 137:     }
 138: 
 139:     @Override
 140:     public int onStartCommand(Intent intent, int flags, int startId) {
 141:         switch (intent.getAction()) {
 142:             case LOCAL_SERVICE_CMD_SETUP_CHANGED:
 143:                 onSetupChanged();
 144:                 return START_NOT_STICKY;
 145:             default:
 146:                 return super.onStartCommand(intent, flags, startId);
 147:         }
 148:     }
 149: 
 150:     @Override
 151:     public void onCreate() {
 152:         super.onCreate();
 153:         mContactsProvider = new ContactsProvider(this);
 154:     }
 155: 
 156:     @Override
 157:     public void onDestroy() {
 158:         mContactsProvider.destroy();
 159:         super.onDestroy();
 160:     }
 161: 
 162:     @Override
 163:     public void onReady() {
 164:         Log.e(TAG, "onReady()");
 165:         super.onReady();
 166:         updateNotification();
 167: 
 168:         // Setup always-on hot-word detector here (see: VoiceInteractionService#onReady()) for
 169:         // details.
 170:     }
 171: 
 172:     private boolean isSetupComplete() {
 173:         boolean setupComplete = PreferencesController.getInstance(this).isUserSignedIn()
 174:                 && hasAllPermissions(this) && isNotificationListener();
 175:         Log.d(TAG, "isSetupComplete: " + setupComplete);
 176:         return setupComplete;
 177:     }
 178: 
 179:     /**
 180:      * @return true if this application has all required dangerous permissions (permissions the
 181:      * user is able to grant).
 182:      */
 183:     public static boolean hasAllPermissions(Context context) {
 184:         for (String permission : REQUIRED_PERMISSIONS) {
 185:             if (context.checkSelfPermission(permission) != PackageManager.PERMISSION_GRANTED) {
 186:                 Log.d(TAG, "Missing permission: " + permission);
 187:                 return false;
 188:             }
 189:         }
 190:         return true;
 191:     }
 192: 
 193:     private boolean isNotificationListener() {
 194:         ComponentName component = new ComponentName(this,
 195:                 VoiceNotificationListenerService.class);
 196:         NotificationManager notificationManager = getSystemService(NotificationManager.class);
 197:         return notificationManager.isNotificationListenerAccessGranted(component);
 198:     }
 199: 
 200:     private void onSetupChanged() {
 201:         Log.d(TAG, "onSetupChanged");
 202:         int items = mListeners.beginBroadcast();
 203:         for (int i = 0; i < items; i++) {
 204:             try {
 205:                 mListeners.getBroadcastItem(i).setupChanged();
 206:             } catch (RemoteException e) {
 207:                 Log.e(TAG, "Unable to notify broadcast item "
 208:                         + mListeners.getBroadcastItem(i), e);
 209:             }
 210:         }
 211:         mListeners.finishBroadcast();
 212:         updateNotification();
 213:     }
 214: 
 215:     private void updateNotification() {
 216:         if (mNotificationManager == null) {
 217:             mNotificationManager = getSystemService(NotificationManager.class);
 218:             NotificationChannel channel = new NotificationChannel(CHANNEL_ID,
 219:                     getString(R.string.app_name), NotificationManager.IMPORTANCE_DEFAULT);
 220:             mNotificationManager.createNotificationChannel(channel);
 221:         }
 222:         if (isSetupComplete()) {
 223:             Log.d(TAG, "updateNotification(): is setup complete = true");
 224:             mNotificationManager.cancel(NOTIFICATION_ID);
 225:             return;
 226:         }
 227:         Log.d(TAG, "updateNotification(): is setup complete = false");
 228:         Intent intent = new Intent(this, SignInActivity.class);
 229:         intent.setFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
 230:         PendingIntent pendingIntent = PendingIntent.getActivity(this, 0,
 231:                 intent, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
 232: 
 233:         Notification notification = new NotificationCompat.Builder(this, CHANNEL_ID)
 234:                 .setSmallIcon(R.drawable.ic_launcher)
 235:                 .setColor(getColor(R.color.car_ui_color_accent))
 236:                 .setContentTitle(getString(R.string.notification_setup_title))
 237:                 .setContentText(getString(R.string.notification_setup_text))
 238:                 .setContentIntent(pendingIntent)
 239:                 .build();
 240: 
 241:         mNotificationManager.notify(NOTIFICATION_ID, notification);
 242:     }
 243: 
 244:     @NonNull
 245:     @Override
 246:     public Set<String> onGetSupportedVoiceActions(@NonNull Set<String> voiceActions) {
 247:         Set<String> result = new HashSet<>(voiceActions);
 248:         result.retainAll(SUPPORTED_VOICE_ACTIONS);
 249:         return result;
 250:     }
 251: 
 252: }
