 117:     }
 118: 
 119:     void setUsername(String username) {
 120:         getRemote(() -> {
 121:             mInteractionService.setUsername(username);
 122:             return null;
 123:         });
 124:     }
 125: 
 126:     boolean hasAllPermissions() {
