 153:      */
 154:     public Contact getContact(String query, @Nullable String deviceAddress) {
 155:         return getRemote(() -> mInteractionService.getContact(query, deviceAddress));
 156:     }
 157: 
 158:     private interface RemoteSupplier<T> {
 159:         T get() throws RemoteException;
 160:     }
 161: 
 162:     private <T> T getRemote(RemoteSupplier<T> supplier) {
 163:         try {
 164:             if (mInteractionService == null) {
