  16: package com.android.car.voicecontrol.actuators;
  17: 
  18: import android.annotation.Nullable;
  19: import android.app.PendingIntent;
  20: import android.content.BroadcastReceiver;
  21: import android.content.Context;
  22: import android.content.Intent;
  23: import android.content.IntentFilter;
  24: import android.net.Uri;
  25: import android.os.Bundle;
  26: import android.telecom.TelecomManager;
  27: import android.telephony.SmsManager;
  28: import android.text.TextUtils;
  29: import android.util.Log;
  30: import android.util.Pair;
  31: 
  32: import com.android.car.telephony.common.Contact;
  33: import com.android.car.telephony.common.PhoneNumber;
  34: import com.android.car.voicecontrol.InteractionServiceClient;
  35: import com.android.car.voicecontrol.R;
  36: import com.android.car.voicecontrol.TextToSpeech;
  37: import com.android.i18n.phonenumbers.NumberParseException;
  38: import com.android.i18n.phonenumbers.PhoneNumberUtil;
  39: import com.android.i18n.phonenumbers.Phonenumber;
  40: 
  41: import java.util.Arrays;
  42: import java.util.List;
  43: 
  44: /**
  45:  * Actuator that interacts with the telephony stack
  46:  */
  47: public class CommActuator implements SkillRouter.Actuator {
  48:     private static final String TAG = "Mica.CommActuator";
  49:     public static final String SMS_RESULT_ACTION = "com.android.car.voicecontrol.sms";
  50: 
  51:     private TelecomManager mTelecomManager;
  52:     private SmsManager mSmsManager;
  53:     private PhoneNumberUtil mPhoneNumberUtil = PhoneNumberUtil.getInstance();
  54:     private InteractionServiceClient mInteractionService;
  55:     private Context mContext;
  56:     private BroadcastReceiver mBroadcastReceiver = new BroadcastReceiver() {
  57:         @Override
  58:         public void onReceive(Context context, Intent intent) {
  59:             Log.d(TAG, "SMS send result: " + getResultCode());
  60:         }
  61:     };
  62:     private int mMaxQuestionRetries;
  63: 
  64:     @Override
  65:     public List<Skill> onCreate(Context context) {
  66:         mContext = context;
  67:         mTelecomManager = (TelecomManager) context.getSystemService(Context.TELECOM_SERVICE);
  68:         mSmsManager = SmsManager.getDefault();
  69:         mInteractionService = new InteractionServiceClient(context);
  70:         mInteractionService.connect();
  71:         registerSMSResultReceiver();
  72:         mMaxQuestionRetries = context.getResources()
  73:                 .getInteger(R.integer.boolean_question_max_retries);
  74: 
  75:         return Arrays.asList(
  76:                 new Skill("call (to )?(.*)$", (args, tts) -> call(args[2], tts)),
  77:                 new Skill("send (a )?message (to )?(.*)$", (args, tts) ->
  78:                         sendSMS(args[3], tts))
  79:         );
  80:     }
  81: 
  82:     private void registerSMSResultReceiver() {
  83:         IntentFilter intentFilter = new IntentFilter(SMS_RESULT_ACTION);
  84:         mContext.registerReceiver(mBroadcastReceiver, intentFilter,
  85:                 Context.RECEIVER_NOT_EXPORTED);
  86:     }
  87: 
  88:     @Override
  89:     public void onDestroy() {
  90:         mInteractionService.disconnect();
  91:         mContext.unregisterReceiver(mBroadcastReceiver);
  92:     }
  93: 
  94:     private boolean call(String query, TextToSpeech tts) {
  95:         Log.d(TAG, "callContact: " + query);
  96: 
  97:         if (mTelecomManager.getPhoneAccountsSupportingScheme("tel").isEmpty()) {
  98:             tts.speak(R.string.speech_reply_phone_not_available);
  99:             return true;
 100:         }
 101: 
 102:         Pair<String, String> numberAndName = getPhoneNumberAndName(query);
 103:         if (numberAndName == null) {
 104:             Log.d(TAG, "Phone not found for query: " + query);
 105:             return false;
 106:         }
 107: 
 108:         tts.ask(tts.createBooleanQuestionCallback(affirmative -> {
 109:             if (!affirmative) {
 110:                 tts.speak(R.string.speech_reply_unrecognized_contact);
 111:                 return;
 112:             }
 113:             doCall(numberAndName.first, numberAndName.second, tts);
 114:         }, mMaxQuestionRetries, false), R.string.speech_reply_confirm_calling_contact,
 115:                 numberAndName.second, numberAndName.first);
 116:         return true;
 117:     }
 118: 
 119:     private Pair<String, String> getPhoneNumberAndName(String query) {
 120:         if (isPhoneNumber(query)) {
 121:             return Pair.create(query, query);
 122:         }
 123:         Contact contact = mInteractionService.getContact(query, null);
 124:         String number = getPhoneNumberFromContact(contact);
 125:         if (number == null) {
 126:             Log.d(TAG, "Contact doesn't have a phone: "
 127:                     + (contact != null ? contact.getDisplayName() : null));
 128:             return null;
 129:         }
 130:         return Pair.create(number, contact.getDisplayName());
 131:     }
 132: 
 133:     private boolean isPhoneNumber(String value) {
 134:         try {
 135:             Phonenumber.PhoneNumber number = mPhoneNumberUtil.parse(value, "US");
 136:             return true;
 137:         } catch (NumberParseException ex) {
 138:             return false;
 139:         }
 140:     }
 141: 
 142:     @Nullable
 143:     private String getPhoneNumberFromContact(@Nullable Contact contact) {
 144:         if (contact == null) {
 145:             return null;
 146:         }
 147:         if (contact.getPrimaryPhoneNumber() != null
 148:                 && !TextUtils.isEmpty(contact.getPrimaryPhoneNumber().getRawNumber())) {
 149:             return contact.getPrimaryPhoneNumber().getRawNumber();
 150:         }
 151:         for (PhoneNumber number : contact.getNumbers()) {
 152:             String value = number.getRawNumber();
 153:             if (value != null && !value.isEmpty()) {
 154:                 return value;
 155:             }
 156:         }
 157:         return null;
 158:     }
 159: 
 160:     private void doCall(String number, String name, TextToSpeech tts) {
 161:         try {
 162:             Uri uri = Uri.fromParts("tel", number, null);
 163:             Bundle extras = new Bundle();
 164:             extras.putBoolean(TelecomManager.EXTRA_START_CALL_WITH_SPEAKERPHONE, true);
 165:             mTelecomManager.placeCall(uri, extras);
 166:             tts.speak(R.string.speech_reply_okay_calling, name);
 167:         } catch (Exception ex) {
 168:             tts.speak(R.string.speech_reply_error_calling, name);
 169:         }
 170:     }
 171: 
 172:     private boolean sendSMS(String query, TextToSpeech tts) {
 173:         Log.d(TAG, "sendSMSContact: " + query);
 174: 
 175:         Pair<String, String> numberAndName = getPhoneNumberAndName(query);
 176:         if (numberAndName == null) {
 177:             Log.d(TAG, "Phone not found for query: " + query);
 178:             return false;
 179:         }
 180: 
 181:         tts.ask(tts.createBooleanQuestionCallback(affirmative -> {
 182:             if (!affirmative) {
 183:                 tts.speak(R.string.speech_reply_unrecognized_contact);
 184:                 return;
 185:             }
 186:             doSendSMS(numberAndName.first, numberAndName.second, tts);
 187:         }, mMaxQuestionRetries, false),
 188:                 R.string.speech_reply_confirm_send_sms_contact, numberAndName.second,
 189:                 numberAndName.first);
 190:         return true;
 191:     }
 192: 
 193:     private void doSendSMS(String number, String name, TextToSpeech tts) {
 194:         tts.ask(results -> {
 195:             if (results.isEmpty()) {
 196:                 tts.speak(R.string.speech_reply_not_recognized);
 197:                 return;
 198:             }
 199:             try {
 200:                 Intent intent = new Intent(SMS_RESULT_ACTION);
 201:                 PendingIntent sentIntent = PendingIntent.getBroadcast(mContext, 0, intent,
 202:                         PendingIntent.FLAG_IMMUTABLE);
 203:                 mSmsManager.sendTextMessage(number, null, results.get(0), sentIntent, null);
 204:                 tts.speak(R.string.speech_reply_okay_sending_sms, name);
 205:             } catch (Exception ex) {
 206:                 tts.speak(R.string.speech_reply_error_sending_sms, name);
 207:             }
 208:         }, R.string.speech_reply_request_message);
 209:     }
 210: }

